function c(n){const t=Math.max(0,n-75e3),r=[{min:0,max:4e5,rate:0,label:"Up to ₹4,00,000"},{min:4e5,max:8e5,rate:5,label:"₹4,00,001 - ₹8,00,000"},{min:8e5,max:12e5,rate:10,label:"₹8,00,001 - ₹12,00,000"},{min:12e5,max:16e5,rate:15,label:"₹12,00,001 - ₹16,00,000"},{min:16e5,max:2e6,rate:20,label:"₹16,00,001 - ₹20,00,000"},{min:2e6,max:24e5,rate:25,label:"₹20,00,001 - ₹24,00,000"},{min:24e5,max:1/0,rate:30,label:"Above ₹24,00,000"}];let e=0;const s=[];for(const a of r){if(t<=a.min)break;const o=Math.min(t,a.max)-a.min,m=o*a.rate/100;e+=m,s.push({slab:a.label,rate:a.rate,taxableAmount:o,tax:m})}t<=12e5?e=0:e=Math.min(e,t-12e5);const l=e*.04,i=e+l,b=n>0?i/n*100:0;return{taxableIncome:t,totalTax:e,cess:l,totalTaxWithCess:i,effectiveRate:b,slabBreakdown:s}}function f(n,x=0){const t=Math.max(0,n-5e4-x),r=[{min:0,max:25e4,rate:0,label:"Up to ₹2,50,000"},{min:25e4,max:5e5,rate:5,label:"₹2,50,001 - ₹5,00,000"},{min:5e5,max:1e6,rate:20,label:"₹5,00,001 - ₹10,00,000"},{min:1e6,max:1/0,rate:30,label:"Above ₹10,00,000"}];let e=0;const s=[];for(const a of r){if(t<=a.min)break;const o=Math.min(t,a.max)-a.min,m=o*a.rate/100;e+=m,s.push({slab:a.label,rate:a.rate,taxableAmount:o,tax:m})}t<=5e5&&(e=0);const l=e*.04,i=e+l,b=n>0?i/n*100:0;return{taxableIncome:t,totalTax:e,cess:l,totalTaxWithCess:i,effectiveRate:b,slabBreakdown:s}}export{f as a,c as i};
